--- 和 CfUtils 中的 GetLuaScr() 相同, 独立出来是为了让 本模块 支持单lua场景运行 (不用从主游戏加载)
---@param go UnityEngine.Object
---@param scrPath string
---@return any | nil
function IdolLive3D_Utils.GetLuaScr(go, scrPath)
    if not go or not scrPath then
        return
    end
    local scr = GetLuaBehaviour(go.gameObject, scrPath)
    if scr then
        if isNull(scr.Env) then
            scr:Init()
        end
        if scr.Env then
            return scr.Env
        end
    end
    return nil
end


