function IdolLive3D_Utils.IsReallyPCPlatform()
    local p = Application.platform;
    return     (p == RuntimePlatform.WindowsEditor) 
            or (p == RuntimePlatform.WindowsPlayer) 
            or (p == RuntimePlatform.OSXEditor)
            or (p == RuntimePlatform.OSXPlayer)
            or (p == RuntimePlatform.LinuxEditor)
            or (p == RuntimePlatform.LinuxPlayer)
end


function IdolLive3D_Utils.IsEditorPlatform()
    local p = Application.platform;
    return     (p == RuntimePlatform.WindowsEditor) 
            or (p == RuntimePlatform.OSXEditor)
            or (p == RuntimePlatform.LinuxEditor)
end


