-- ============================== load =======================================

function IdolLive3D_Utils.LoadJsonSync( jsonPath_ )

    local jsonString = ""
    local loader_json = ResourceModule.LoadBundleSync( jsonPath_, nil, true ) -- 不设回调, 不删除资源

    if loader_json.IsSuccess then
        jsonString = tostring(loader_json.ResultObject)
        print("koko - json 加载成功: " .. tostring(jsonPath_) )
    else
        printError( "koko !!! json 加载失败: " .. tostring(jsonPath_) )
        return nil
    end
    -- 原始数据尾端有杂余信息, 比如: "{}: 408484", 需要剥离大括号后面的那些;
    jsonString = IdolLive3D_Utils.StripTail(jsonString)
    
    local json = table.deserialize(jsonString) -- rapidjson.decode()
    return json
end


-- 同步加载:
function IdolLive3D_Utils.LoadPrefabSync( path, parentTF, errorMsg ) 
    local loader = ResourceModule.LoadBundleSync(path, nil, true)
    if loader.IsError == true then 
        printError("加载资源失败; path: " .. tostring(path) .. "; " .. tostring(errorMsg)  )
        return
    end 
    ---
    local newgo = loader:Instantiate()
    newgo.transform:SetParent( parentTF )
    newgo.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
    return newgo.transform
end




-- 剥离 json 文件尾部数据:
function IdolLive3D_Utils.StripTail( s )
    local ts = string.reverse(s)    -- 倒序
    local _,i = string.find(ts, '}') --获取k在反转后的str字符串ts的位置
    local m = string.len(ts) - i + 1 --获取k在字符串str中的位置
    local ret = string.sub(s, 1, m)  --返回字符串str字符k之前的部分
    return ret
end




