function IdolLive3D_Utils.CloseEnough( a_,b_, threshold_ )
    if type(a_) ~= "number" or type(b_) ~= "number" or type(threshold_) ~= "number"  then 
        printError( "参数异常, a: " .. tostring(a_) .. ", b:" .. tostring(b_) .. ", threshold: " .. tostring(threshold_) ) 
    end
    return (Mathf.Abs( checkNumber(a_) - checkNumber(b_) ) < checkNumber(threshold_) )
end


function IdolLive3D_Utils.CopyToLookAtIK( lookAtIKComp_, data_ )
    if isNull(data_) then
        printError("参数 data_ 为空")
        return 
    end 
    lookAtIKComp_.solver.bodyWeight = data_.bodyWeight
    lookAtIKComp_.solver.headWeight = data_.headWeight
    lookAtIKComp_.solver.eyesWeight = data_.eyesWeight
    lookAtIKComp_.solver.clampWeight = data_.clampWeight
    lookAtIKComp_.solver.clampWeightHead = data_.clampWeightHead
    lookAtIKComp_.solver.clampWeightEyes = data_.clampWeightEyes
    lookAtIKComp_.solver.clampSmoothing = data_.clampSmoothing
end


