-- 一种安全地获得 深度互动 Version 的方式;
---@param skinId_ integer
---@return number @ 1,2
function IdolLive3D_Utils.GetLive3DVersion( skinId_ )
    assert( type(skinId_) == "number" )
    local tableFile = settingMgr:Get(AutoIds.IdSetting6120) -- TableFile, 
    local length = tableFile:GetRowCount()
    for i=1,length do -- (实际从表格第 5 行开始读)
        local row = tableFile:GetRow(i) -- TableFileRow
        local skinId = checkInt( row:Get("skinId") )
        if skinId == checkInt(skinId_) then 
            local version = 1
            if row.HeaderInfos:ContainsKey("Version") then
                version = (checkInt(row:Get("Version")) == 2) and 2 or 1
            end 
            return version
        end 
    end
    printError("卡牌互动表 里没找到 skinId = " .. tostring(skinId_))
    return 1
end



