---@param skinId integer
---@return Live3DCardVo | nil
function IdolLive3D_Utils.GetLive3DCardVoRow( skinId_ )
    skinId_ = checkInt(skinId_)
    ---@type IdolLive3D_States
    local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
    if IdolLive3D_States.isOpenIdolLive3D == false then -- 总开关
        return nil
    end
    --- 读取配表 Live3DCardVo:
    local live3DCardVoRow = IdolLive3D_Utils.GetLive3DCardVo( skinId_ )
    if isNull(live3DCardVoRow) then 
        --print("koko - 爱豆3D深度互动: 皮肤:" .. tostring(skinId_) .. " 未在 卡牌互动表 中找到 此角色/皮肤, 故暂不开放")
        return nil
    end 
    if live3DCardVoRow.isInteractive ~= true then 
        --print("koko - 爱豆3D深度互动: 皮肤:" .. tostring(skinId_) .. " 卡牌互动表 中存在 此角色/皮肤, 但它 isInteractive 不为 true, 故暂不开放")
        return nil
    end 
    return live3DCardVoRow
end


---@return boolean @ 是否购买 本皮肤的互动功能
function IdolLive3D_Utils.IsBuyThisSkinsLive3D( skinId_ )
    skinId_ = checkInt(skinId_)
    ---@type IdolLive3D_States
    local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
    if IdolLive3D_States.isOpenIdolLive3D == false then -- 总开关
        return false
    end
    --- 
    local live3DCardVoRow = IdolLive3D_Utils.GetLive3DCardVoRow(skinId_) -- 读取配表 Live3DCardVo:
    if isNull(live3DCardVoRow) then 
        printError("koko - 没拿到 Live3DCardVo 配表 对应行, 这个皮肤是不是不支持 深度互动 ?")
        return false
    end 
    ---
    if IdolLive3D_Utils.isRegionSupportSellingSeparately() == false then 
        print("皮肤和深度互动 不支持 分开售卖")
        return true -- "皮肤与深度互动分开售卖" 功能; 无需检测道具
    end  
    print("皮肤和深度互动 支持 分开售卖")

    
    local goodId = live3DCardVoRow.itemId
    if goodId < 0 then 
        return true -- 说明本皮肤的互动不需要购买, 自动赠送
    end 
    ---
    local curNum = GoodsUtils.GetThingNo(goodId) -- 道具 实际拥有数
    local isBuy = curNum > 0
    if isBuy == false then 
        printInfo("没购买本皮肤: " .. tostring(skinId_) .. " 的 深度互动功能; 去买道具: " .. tostring(goodId) )
    end 
    return isBuy
    
end



