function IdolLive3D_Utils.GetPlayerDojoDeepTimes( skinId_ )
    local idStr = tostring(skinId_) 
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local dojo = playerComp:GetPlayerDojo()
    dojo.cardSkinDeepTimes = checkTable(dojo.cardSkinDeepTimes)
    dojo.cardSkinDeepTimes[idStr] = checkTable(dojo.cardSkinDeepTimes[idStr])
    dojo.cardSkinDeepTimes[idStr].deepTimes = checkTable(dojo.cardSkinDeepTimes[idStr].deepTimes)
