---@return table
function IdolLive3D_Utils.GetLive3DTouchTipsDojosBySkinId( skinId_ )
    local vos = IdolLive3D_Utils.GetLive3DTouchTipsVosBySkinId( skinId_ )

    if table.count(vos) == 0 then 
        return {}
    end   
    
    local deepTimes = IdolLive3D_Utils.GetPlayerDojoDeepTimes(skinId_)
    for i=1, table.count(vos) do 
        --printError( tostring(i) .. ": " .. table.dump( vos[i] ) )
        if type( deepTimes[vos[i].key]) == "number" then 
            vos[i].touchedNum = deepTimes[vos[i].key]
        else 
            vos[i].touchedNum = 0
        end
    end 
    return vos;
end




