-- runtime 专用:
-- 遍历 爱豆场景 顶层 GOs, 找出其中名字为 参数 name_ 的 gameobj:
---@return UnityEngine.Transform
function IdolLive3D_Utils.FindRootTransformInIdol3DScene(name_)
    ---@type IdolLive3D_States
    local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
    local sceneManagement     = SceneManagement:GetInstance()

    local sceneIns = sceneManagement:GetSceneInstance(IdolLive3D_Utils.GetIdolLive3DsceneId())
    if isNotNull(sceneIns) then 
        ---@type UnityEngine.SceneManagement.Scene
        local scene = sceneIns:GetScene()
        assert( scene )
        if scene:IsValid() and scene.isLoaded then 

            local rootObjects = scene:GetRootGameObjects() -- GameObject[]
            for i=0,rootObjects.Length-1 do
                local go = rootObjects[i]
                if isNotNull(go) and go.name == tostring(name_) then 
                    return go.transform
                end 
            end
        else 
            printError("koko - 异常, 爱豆场景未加载")
        end 
    end 
    printError("koko - 异常, 未找到 " .. tostring(name_) .. " 这个根节点")
    return nil
end



function IdolLive3D_Utils.SetMainLight( rotation_, color_, intensity_ ) 

    local DirectionalLightTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("Directional Light") -- 场景中真正在起作用的主光源
    assert( isNotNull(DirectionalLightTF) )
    local DirectionalLight = KTool.GetComponent(DirectionalLightTF.gameObject, typeof(Light))
    assert(DirectionalLight)
    ---
    DirectionalLightTF.rotation = rotation_
    DirectionalLight.color = color_
    DirectionalLight.intensity = intensity_
end


function IdolLive3D_Utils.CopyCameraCustomData( srcCameraTF_ )

    local mainCamera = IdolLive3D_Utils.GetMainCamera() 
    local dst_CameraCustomData = KTool.GetComponent(mainCamera.gameObject, typeof(CS.CameraCustomData))
    local src_CameraCustomData = KTool.GetComponent(srcCameraTF_.gameObject, typeof(CS.CameraCustomData))
    if isNotNull(dst_CameraCustomData) and isNotNull(src_CameraCustomData) then 
        dst_CameraCustomData:CopyData( src_CameraCustomData )
    else 
        printError("异常, 没找到 CameraCustomData 组件, 请检查场景 prefab")
    end 
end



