-- 查找爱豆场景中 第一个激活态的 建筑tf
---@return UnityEngine.Transform
function IdolLive3D_Utils.FindFirstActiveBuildTF( buildsRootTF )

    if isNull(buildsRootTF) or isNull(buildsRootTF.childCount) then 
        printError("参数为nil")
        return nil
    end 

    for i=0, buildsRootTF.childCount-1 do 
        local childTF = buildsRootTF:GetChild(i)
        if childTF.gameObject.activeInHierarchy == true then 
            return childTF
        end 
    end

    printError("爱豆3D场景中 没找到 _Builds_ 节点")
    return nil
end



function IdolLive3D_Utils.ReserBuildPos( buildsRootTF, newPos_ )
    local buildTF = IdolLive3D_Utils.FindFirstActiveBuildTF(buildsRootTF)
    if isNull(buildTF) then 
        return
    end 
    if isNull(newPos_.x) or isNull(newPos_.y) or isNull(newPos_.z) then 
        printError("参数 newPos_ 异常")
        return
    end 
    buildTF.position = Vector3( checkNumber(newPos_.x), checkNumber(newPos_.y), checkNumber(newPos_.z) )
end




