-- 搜索一个角色所有子孙节点, 找出所有 "携带了 string id" 的 collider 节点
---@param roleTF_ UnityEngine.Transform @ 
---@param includeInactive_ boolean
---@return table
function IdolLive3D_Utils.FindAllRoleColliders( roleTF_, includeInactive_ )
    if type(includeInactive_) ~= "boolean" then 
        includeInactive_ = true
    end 
    local retMaps = {} -- key:idStr, Val:collider
    local colliders = roleTF_:GetComponentsInChildren(typeof(Collider),includeInactive_) -- 包含自己
    for i=0, colliders.Length-1 do 
        ---@type UnityEngine.Collider
        local collider = colliders[i]
        local idComp = KTool.GetComponent(collider.gameObject, typeof(CS.Game.Native.Common.ID))
        if isNotNull(idComp) then 
            if string.isEmpty(idComp.stringId) == false then 
                retMaps[idComp.stringId] = collider
            end 
        end 
    end
    return retMaps
end



---@return number @ 子孙节点个数
function IdolLive3D_Utils.CountGameObjectChildrenNumRecursively( parent_ )
    local comps = parent_:GetComponentsInChildren(typeof(Transform),true) -- 包含自己, 包含隐藏节点
    return comps.Length-1 -- 扣除自己
end



