function IdolLive3D_Utils.SetVCamNearFarClipPlane( vcam_, nearPlane_, farPlane_ )
    local lens = vcam_.m_Lens 
    lens.NearClipPlane = checkNumber(nearPlane_)
    lens.FarClipPlane = checkNumber(farPlane_)
