-- 将一个 Vector3 值, 转换到指定的 新坐标系中:
function IdolLive3D_Utils.TransformVector3( originDir_, xAxis_, yAxis_, zAxis_ )
    return originDir_.x * xAxis_ + originDir_.y * yAxis_ + originDir_.z * zAxis_
end


---@return UnityEngine.Vector3
function IdolLive3D_Utils.MatrixMult( mtx_, vec3_ )
    local r4 = mtx_ * Vector4(vec3_.x, vec3_.y, vec3_.z, 0.0)
    return Vector3( r4.x, r4.y, r4.z )
end



function IdolLive3D_Utils.Json2Vector3(json_)
    assert( type(json_.x) == "number" )
    assert( type(json_.y) == "number" )
    assert( type(json_.z) == "number" )
    return Vector3( checkNumber(json_.x), checkNumber(json_.y), checkNumber(json_.z) )
end 



---@param key_ string 
---@return boolean
function IdolLive3D_Utils.IsKeyValid(key_)
    return      (string.isEmpty(key_) == false)
            and (string.find(key_, ' ') == nil)
end



--- list_ 是个数组, 每个元素内涵一个 key:string 值; 检查这些 key 是否都是唯一的 (没有重复)
---@return boolean
function IdolLive3D_Utils.IsEachKeyUnique( list_ )
    assert( isTable(list_) )
    local ents = {}
    for _,e in pairs(list_) do 
        local key = tostring(e.key)
        if ents[key] == nil then 
            ents[key] = 1
        elseif ents[key] == 1 then 
            return false
        end
    end
    return true
end


-- 删除字符串 尾部空格
function IdolLive3D_Utils.TrimTrailingSpaces(s)  
    return s:match("^(.-)%s*$")  
end  




-- ================================= 和谐模式 ========================================

local hexie = 
{
    folder          = "/live3d/",
    bootName        = "boot.md",       -- 引导文件
    isHeXie_name    = "professional_config.md",  -- 玩家可删除的主文件; 删除后即解除和谐封印
}


---@param isDebugLog_ boolean | nil
function IdolLive3D_Utils._IsFindHeXieFile( isDebugLog_ )  
    local folderPath = PathUtility.Combine(Application.persistentDataPath, hexie.folder)
    local bootPath = PathUtility.Combine(folderPath, hexie.bootName)
    local isHexiePath = PathUtility.Combine(folderPath, hexie.isHeXie_name)
    IdolLive3D_Utils.Log( isDebugLog_, "深度互动, 和谐文件目录 = " ..tostring(folderPath) )
    ---
    if Directory.Exists( folderPath ) == false then 
        Directory.CreateDirectory( folderPath )
    end 
    -- 引导程序:
    if File.Exists(bootPath) == false then 
        File.Create(bootPath)
        File.Create(isHexiePath)
    end 
    ---
    local isFind = File.Exists(isHexiePath)
    return isFind
end


---@return boolean @ true:找到文件,并删除之; false:未找到文件, 啥也没干
function IdolLive3D_Utils.TryReMoveHeXieFile()  
    local folderPath = PathUtility.Combine(Application.persistentDataPath, hexie.folder)
    local bootPath = PathUtility.Combine(folderPath, hexie.bootName)
    local isHexiePath = PathUtility.Combine(folderPath, hexie.isHeXie_name)
    ---
    if Directory.Exists( folderPath ) == false then 
        return false
    end
    --- 
    if File.Exists(isHexiePath) == false then 
        return false
    end
    --- 
    File.Delete(isHexiePath)
    print("删除文件: " ..tostring(isHexiePath))
    return true
end


-- ------------------------------------------------
--  (1) 判断本机器 是否处于 和谐模式中
-- ------------------------------------------------
---@param isDebugLog_ boolean | nil
---@return boolean @ 返回 true:表示在和谐模式中
function IdolLive3D_Utils.IsAppInHeXieMode( isDebugLog_ )  
    --- 本服务区是否支持 和谐功能:
    if IdolLive3D_Utils.isRegionSupportHeXie() == false then 
        IdolLive3D_Utils.Log( isDebugLog_, "本服务区 不支持 和谐模式" )
        return false
    end
    --- ====
    IdolLive3D_Utils.Log( isDebugLog_, "本服务区 支持 和谐模式" )
    local isFindHeXieFile = IdolLive3D_Utils._IsFindHeXieFile()  
    return isFindHeXieFile
end  

-- ------------------------------------------------
--  (2) 判断本皮肤 是否拥有 61和谐影子道具
-- ------------------------------------------------
function IdolLive3D_Utils.IsFindHeXieGoods( skinId_ )
    --- 读取配表 Live3DCardVo:
    local voRow = IdolLive3D_Utils.GetLive3DCardVo( skinId_ )
    if isNull(voRow) then 
        return false -- 深度互动配表里没这个皮肤的数据, 自然没有和谐道具
    end 
    local heXieGoodsId = voRow.heXieId
    if heXieGoodsId <= 0 then 
        return false -- 此皮肤不设置影子道具
    end 
    ---
    local isFindHeXieGoods = (GoodsUtils.GetThingNo(heXieGoodsId) > 0)
    return isFindHeXieGoods
end

-- ===============================================
--  结合上面的 (1) 和 (2); 判断本皮肤 是否处于 和谐模式
-- ===============================================

---@param isDebugLog_ boolean | nil
function IdolLive3D_Utils.IsThisSkinInHeXieMode( skinId_, isDebugLog_ )
    skinId_ = checkInt(skinId_)
    local isAppInHeXieMode = IdolLive3D_Utils.IsAppInHeXieMode() 
    local isFindHeXieGoods = IdolLive3D_Utils.IsFindHeXieGoods(skinId_)
    --- 
    IdolLive3D_Utils.Log( isDebugLog_, "(1)本机器 是否处于 和谐模式:  " .. tostring(isAppInHeXieMode) )
    IdolLive3D_Utils.Log( isDebugLog_, "(2)本皮肤 是否找到 和谐影子道具:  " .. tostring(isFindHeXieGoods) )
    local finalHeXie = (isAppInHeXieMode==true) and (isFindHeXieGoods==true)
    return finalHeXie
end



-- 调用本函数说明玩家已经能进入互动了, 此时只关心 和谐问题
function IdolLive3D_Utils.GetRolePrefabPath( skinId_, isDemo_ )
    skinId_ = checkInt(skinId_)
    local live3DCardVoRow = IdolLive3D_Utils.GetLive3DCardVoRow( skinId_ )
    assert(isNotNull(live3DCardVoRow))
    ---
    local finalHeXie = false
    if isDemo_ == true then 
        -- demo 要走特殊逻辑: demo不支持破解
        local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinId_)
        finalHeXie = (cardSkinVo.isNormal == false)
        --IdolLive3D_Utils.Log( isDebugLog_, "demo 模式, 是否和谐: " .. tostring(finalHeXie) )
    else 
        finalHeXie = IdolLive3D_Utils.IsThisSkinInHeXieMode( skinId_, true )
    end 
    ---
    if finalHeXie then 
        print("正式走 和谐模式")
        return IdolLive3D_Utils._GetPrefabHexXiePath(live3DCardVoRow.rolePrefabPath)
    else 
        print("正式走 非和谐模式")
        return live3DCardVoRow.rolePrefabPath
    end 
end



