-- 从 "Arts/Prefab_lobby/103021_lobby.prefab" 变为 "Arts/Prefab_lobby/103021_lobby_hexie.prefab"
function IdolLive3D_Utils._GetPrefabHexXiePath( prefabPath_ )
    -- 找到最后一个斜杠和最后一个点的位置  
    local lastSlashIndex = prefabPath_:match(".*()/")  
    local lastDotIndex = prefabPath_:match(".*()%.")  
    -- 提取路径的前缀和后缀  
    local prefix = prefabPath_:sub(1, lastSlashIndex)  
    local filename = prefabPath_:sub(lastSlashIndex + 1, lastDotIndex - 1)  
    local suffix = prefabPath_:sub(lastDotIndex)  
    -- 拼接变体字符串  
    return prefix .. filename .. "_hexie" .. suffix 
end


