---@param isCheck_ boolean
function IdolLive3D_Utils.ClearAllSceneNodes( isCheck_ )
    local roleRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Role_")
    local runtimeRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Runtime_")
    local buildsRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Builds_")
    ---
    if isCheck_ == true then 
        if IdolLive3D_Utils.CountGameObjectChildrenNumRecursively(roleRootTF) > 0 then
            printError("异常, 发现 深度场景节点内残留内容; 节点:" .. tostring(roleRootTF.name) )
        end
        if IdolLive3D_Utils.CountGameObjectChildrenNumRecursively(runtimeRootTF) > 0 then
            printError("异常, 发现 深度场景节点内残留内容; 节点:" .. tostring(runtimeRootTF.name) )
        end
        if IdolLive3D_Utils.CountGameObjectChildrenNumRecursively(buildsRootTF) > 0 then
            printError("异常, 发现 深度场景节点内残留内容; 节点:" .. tostring(buildsRootTF.name) )
        end
    end 
    KTool.DestroyGameObjectChildren( roleRootTF.gameObject )
    KTool.DestroyGameObjectChildren( runtimeRootTF.gameObject )
    KTool.DestroyGameObjectChildren( buildsRootTF.gameObject )
end


